package com.lolfm.simulator;import static org.assertj.core.api.Assertions.*;import com.lolfm.domain.Position;import org.junit.jupiter.api.Test;class ProgressionSnapshotTest{private com.lolfm.domain.PlayerSnapshot top(GameState s){return new SnapshotFactory().create(s).getPlayerSnapshots().stream().filter(p->p.getTeamSide()==TeamSide.BLUE&&p.getPosition()==Position.TOP).findFirst().orElseThrow();}@Test void pastSnapshotIsImmutable(){GameState s=LateGameTestSupport.state();var before=top(s);s.getBlueTeamState().playerAt(Position.TOP).getProgressionState().awardExperience(ExperienceSource.KILL,2400,10);assertThat(before.getLevel()).isOne();assertThat(top(s).getLevel()).isEqualTo(6);}@Test void snapshotRatiosUseCurrentThresholds(){GameState s=LateGameTestSupport.state();var p=s.getBlueTeamState().playerAt(Position.TOP);p.getProgressionState().awardExperience(ExperienceSource.LANE_ECONOMY,140,10);p.addGold(600,GoldSource.FARM,10);var x=top(s);assertThat(x.getLevelProgressRatio()).isEqualTo(.5);assertThat(x.getItemProgressRatio()).isEqualTo(.5);}@Test void snapshotCreationDoesNotMutateOrEmit(){GameState s=LateGameTestSupport.state();new SnapshotFactory().create(s);new SnapshotFactory().create(s);assertThat(s.getBlueTeamState().playerAt(Position.TOP).getProgressionState().getTotalExperience()).isZero();}}
